fn git(root:&Path,args:&[&str])->String {let o=Command::new("git").current_dir(root).env("GIT_CONFIG_GLOBAL","/dev/null").env("GIT_CONFIG_NOSYSTEM","1").args(["-c","core.hooksPath=","-c","maintenance.auto=false","-c","gc.auto=0"]).args(args).output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));String::from_utf8(o.stdout).unwrap().trim().into()}
fn main() {let metadata=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let mut f:serde_json::Value=serde_json::from_slice(&fs::read(&metadata).unwrap()).unwrap();let root=std::path::PathBuf::from(f["root"].as_str().unwrap());assert!(root.join(".gitfleet-ssh-fixture").is_file());let repo=root.join("workspace/repository");fs::create_dir_all(&repo).unwrap();git(&repo,&["-c","init.templateDir=","init","-q","-b","main"]);for (k,v) in [("user.name","Native SSH fixture"),("user.email","fixture@example.invalid"),("commit.gpgsign","false"),("core.hooksPath","")] {git(&repo,&["config",k,v]);}fs::write(repo.join("fixture.txt"),b"Native SSH baseline\n").unwrap();git(&repo,&["add","fixture.txt"]);git(&repo,&["commit","-qm","Native SSH baseline"]);let remote=root.join("server.git");git(&root,&["-c","init.templateDir=","clone","--bare","-q",repo.to_str().unwrap(),remote.to_str().unwrap()]);let tree=git(&repo,&["rev-parse","HEAD^{tree}"]);let old=git(&repo,&["rev-parse","HEAD"]);let next=git(&remote,&["-c","user.name=Native SSH fixture","-c","user.email=fixture@example.invalid","commit-tree",&tree,"-p",&old,"-m","Native SSH remote-only commit"]);git(&remote,&["update-ref","refs/heads/main",&next]);git(&repo,&["remote","add","origin",f["url"].as_str().unwrap()]);fs::write(repo.join("fixture.txt"),b"Staged fixture\n").unwrap();git(&repo,&["add","fixture.txt"]);fs::write(repo.join("fixture.txt"),b"Working fixture\n").unwrap();fs::write(repo.join("untracked.txt"),b"Preserve fixture\n").unwrap();let mut options=Options::default();options.remote.ssh=Some(SshPolicy {known_hosts:f["known_hosts"].as_str().unwrap().into(),public_identity:f["public_identity"].as_str().unwrap().into(),agent_socket:f["agent_socket"].as_str().unwrap().into()});let mut app=Application::open(&root.join("state"),options).unwrap();let picker=app.register_directory(&root.join("workspace")).unwrap();app.request(app.epoch(),Request::Create {name:"Native agent SSH acceptance".into(),picker}).unwrap();let Data::Workspaces(list)=app.request(app.epoch(),Request::Workspaces {}).unwrap().data else {panic!()};let workspace=list.active.unwrap();let Data::Inventory(inv)=app.request(app.epoch(),Request::Inventory {workspace:workspace.clone()}).unwrap().data else {panic!()};let worktree=inv.entries[0].id.0.clone();let Data::Review(r)=app.request(app.epoch(),Request::ReviewTrust {workspace:workspace.clone(),worktrees:vec![worktree.clone()]}).unwrap().data else {panic!()};let (cap,_)=app.begin_confirmation(&r.id).unwrap();app.confirm(cap,true,Cancellation::default()).unwrap();app.shutdown().unwrap();drop(app);f["workspace"]=workspace.into();f["worktree"]=worktree.into();f["baseline_oid"]=old.into();f["target_oid"]=next.into();fs::write(metadata,serde_json::to_vec_pretty(&f).unwrap()).unwrap();}
